<template>
  <div class="space-y-6">
    <PageHeader title="设备与凭据" parent="用户" description="每台设备拥有独立凭据，创建和重置时展示一次明文。"><template #actions><button @click="openCreate" class="ios-btn-primary">创建设备</button></template></PageHeader>
    <div class="flex items-center gap-3">
      <span class="text-xs font-medium text-ios-secondary">所属用户</span>
      <select v-model="selectedUser" class="ios-filter-select" @change="page = 1; load()">
        <option value="">全部用户</option>
        <option v-for="user in users" :key="user.id" :value="user.id">{{ user.displayName }} · {{ user.username }}</option>
      </select>
    </div>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading" /><EmptyState v-else-if="!devices.length" title="暂无设备" />
    <DataTable v-else><template #header><th>设备</th><th>用户</th><th>状态</th><th>协议凭据</th><th>操作</th></template><template #body><tr v-for="device in devices" :key="device.id"><td class="p-4 font-semibold text-[15px] text-ios-label">{{ device.name }}<p class="text-xs text-ios-tertiary font-normal mt-0.5">{{ formatTime(device.createdAt) }}</p></td><td class="text-xs text-ios-secondary">{{ users.find(user => user.id === device.userId)?.username || device.userId }}</td><td><StatusBadge :status="device.status" /></td><td><div v-for="credential in device.credentials.filter(item => item.status === 'active')" :key="credential.id" class="flex items-center gap-2 py-1 text-xs"><span>{{ credential.protocol }}</span><button @click="prompt(device, 'reset', credential.protocol)" class="text-ios-blue hover:underline">重置</button><button @click="prompt(device, 'revoke', credential.protocol)" class="text-ios-red hover:underline">撤销</button></div><span v-if="!device.credentials.some(item => item.status === 'active')" class="text-xs text-ios-tertiary">没有有效凭据</span></td><td class="space-x-2"><button @click="prompt(device, 'status')" class="ios-action-btn-secondary">{{ device.status === 'active' ? '禁用' : '启用' }}</button><button @click="prompt(device, 'delete')" class="ios-action-btn-danger">删除</button></td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" title="创建设备" :loading="saving" @confirm="create"><div class="space-y-4 text-sm"><label class="block text-xs font-medium text-ios-secondary">所属用户<select v-model="form.userId" class="form-input-base mt-1.5"><option value="">请选择</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.username }}</option></select></label><label class="block text-xs font-medium text-ios-secondary">设备名称<input v-model="form.name" maxlength="60" class="form-input-base mt-1.5" /></label><div class="space-y-1.5"><div class="flex items-center justify-between"><label class="text-xs font-medium text-ios-secondary">协议</label><span v-if="allowedProtocols.length" class="text-[11px] text-ios-tertiary">已选 {{ form.protocols.length }} 项</span></div><div class="rounded-2xl p-3 bg-[#F5F5F7] border border-black/[0.06]"><div v-if="allowedProtocols.length" class="flex flex-wrap gap-2"><label v-for="protocol in allowedProtocols" :key="protocol" :class="['inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-medium transition-all cursor-pointer select-none active:scale-95', form.protocols.includes(protocol) ? 'bg-ios-blue text-white shadow-[0_2px_6px_rgba(0,113,227,0.25)] ring-1 ring-ios-blue' : 'bg-white text-ios-secondary border border-black/[0.08] hover:text-ios-label hover:border-black/[0.15] hover:bg-black/[0.02]']"><input type="checkbox" v-model="form.protocols" :value="protocol" class="sr-only" /><svg v-if="form.protocols.includes(protocol)" class="w-3.5 h-3.5 shrink-0" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clip-rule="evenodd" /></svg><span>{{ protocol }}</span></label></div><p v-else class="text-xs text-ios-tertiary py-1">请先选择所属用户，以加载该用户允许的协议。</p></div></div></div></FormDrawer>
    <AppDialog v-model="secretDialog" title="设备凭据" description="明文仅在本次操作中展示。请妥善保存，节点更新需要发布配置。" :show-footer="false"><CodePreview :code="secrets" /></AppDialog>
    <ConfirmDialog v-model="confirmVisible" title="确认设备操作" :message="confirmMessage" @confirm="execute" />
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, onMounted, watch } from 'vue'; import { useRoute } from 'vue-router'; import { userAPI, type ProxyUser, type ProxyDevice, type DeviceCredential } from '../api'; import { formatTime } from '../../../app/auth'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import Pagination from '../../../components/Pagination.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import AppDialog from '../../../components/AppDialog.vue'; import CodePreview from '../../../components/CodePreview.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import EmptyState from '../../../components/EmptyState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue';
const route = useRoute(); const users = ref<ProxyUser[]>([]); const devices = ref<ProxyDevice[]>([]); const selectedUser = ref(typeof route.query.userId === 'string' ? route.query.userId : ''); const page = ref(1); const total = ref(0); const error = ref(''); const loading = ref(false);
const drawer = ref(false); const saving = ref(false); const form = reactive({ userId: '', name: '', protocols: ['socks5'] }); const allowedProtocols = computed(() => users.value.find(user => user.id === form.userId)?.allowedProtocols || []); const secretDialog = ref(false); const secrets = ref(''); const target = ref<ProxyDevice | null>(null); const action = ref(''); const protocol = ref(''); const confirmVisible = ref(false); const actionNames: Record<string, string> = { reset: '重置协议凭据', revoke: '撤销协议凭据', status: '切换启用状态', delete: '删除设备' };
// A delete revokes the device's published credentials by itself, so the dialog
// must not tell the Owner to publish anything for it.
const confirmMessage = computed(() => `对 ${target.value?.name || ''} 执行${actionNames[action.value]}？${action.value === 'delete' ? '已发布到节点的该设备凭据会在约一分钟内自动撤销，无需重新发布。' : '授权变更需发布到节点，订阅会按最新状态过滤。'}`);
async function load() { loading.value = true; try { const [result, userResult] = await Promise.all([userAPI.devices(selectedUser.value, page.value), userAPI.list(1, '', 100)]); devices.value = result.items; total.value = result.total; users.value = userResult.items; error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
function changePage(value: number) { page.value = value; load(); }
function openCreate() { Object.assign(form, { userId: selectedUser.value, name: '', protocols: [] }); drawer.value = true; }
function showCredentials(credentials: DeviceCredential[]) { secrets.value = credentials.map(credential => `${credential.protocol}\n用户名: ${credential.username || '—'}\n凭据: ${credential.secret || '—'}${credential.publicKey ? '\n公钥: ' + credential.publicKey : ''}`).join('\n\n'); secretDialog.value = true; }
async function create() { if (saving.value) return; saving.value = true; try { const device = await userAPI.createDevice(form.userId, form.name, form.protocols); drawer.value = false; showCredentials(device.credentials); await load(); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
function prompt(device: ProxyDevice, operation: string, selectedProtocol = '') { target.value = device; action.value = operation; protocol.value = selectedProtocol; confirmVisible.value = true; }
async function execute() { if (!target.value) return; try { if (action.value === 'reset') showCredentials([await userAPI.resetCredential(target.value.id, protocol.value)]); else if (action.value === 'revoke') await userAPI.revokeCredential(target.value.id, protocol.value); else if (action.value === 'status') await userAPI.updateDevice(target.value, target.value.status === 'active' ? 'disabled' : 'active'); else await userAPI.deleteDevice(target.value.id); showToast('设备操作已保存'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } }
watch(() => form.userId, () => { form.protocols = []; }); watch(secretDialog, visible => { if (!visible) secrets.value = ''; }); onMounted(load);
</script>
